#include <stdio.h>
/* 蕴含：只在 1 -> 0 时为假 */
static int imp(int a, int b) { return (!a) || b; }
/* 等价：同真同假 */
static int iff(int a, int b) { return a == b; }

/*
 * ex01：真值表枚举 —— 判定「假言三段论」是否重言式
 * 为什么：教材上写「(p→q)∧(q→r) → (p→r) 是重言式」，但只有把 8 行真值表
 *        全部算出来，你才会真正相信「p 假时整个蕴含自动为真」这条反直觉规则。
 */
int main(void) {
    printf("p q r | p->q q->r p->r | whole\n");
    printf("------+-----------------+------\n");
    int taut = 1;
    for (int p = 0; p < 2; p++)
        for (int q = 0; q < 2; q++)
            for (int r = 0; r < 2; r++) {
                int a = imp(p, q), b = imp(q, r), c = imp(p, r);
                int f = imp(a && b, c);
                printf("%d %d %d |  %d    %d    %d   |  %d%s\n", p, q, r, a, b, c, f,
                       f ? "" : "   <-- counterexample");
                if (!f) taut = 0;
            }
    printf("\nverdict: the formula is %s\n", taut ? "a TAUTOLOGY (valid)" : "NOT a tautology");
    printf("key point: p->q is false only when p=1 and q=0;\n");
    printf("           when p=0 the implication is vacuously true.\n");
    return 0;
}
